begin;
select no_plan();
insert into auth.users(id,email,aud,role) values ('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','reward-test@example.invalid','authenticated','authenticated');
insert into public.quiz_players(user_id,window_start,used,streak,records) values ('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',now(),5,4,9);
select is(public.quiz_left((select p from public.quiz_players p where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee')),5,'five used leaves five');
select ok(abs((select "drop" from public.quiz_shard_rule_version('{"captureRate":1,"powerLevel":9,"legendary":false,"mythical":false}',2))-.2)<1e-12,'v2 hardest drop 20 percent');
create temp table reward_results(k text primary key,v jsonb);
grant all on reward_results to authenticated;
insert into public.quiz_rounds(id,user_id,answer_id,options,veil,hard,range_from,range_to,gifts,bonus_slot,duration_ms) values ('dddddddd-dddd-4ddd-8ddd-dddddddddddd','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',25,array[25,1,2,3],'warp',false,1,151,array['oran-berry','oran-berry','oran-berry','oran-berry'],-1,14000);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","role":"authenticated"}',true);
insert into reward_results values ('answer',public.quiz_answer('dddddddd-dddd-4ddd-8ddd-dddddddddddd',25::smallint));
select is(jsonb_array_length((select v->'chests' from reward_results where k='answer')),2,'combo and special retain item chests');
select is((select count(*)::int from public.quiz_chest_shard_events),2,'both entitlements visible to owner');
select is((select (v->>'chest_reward_version')::int from reward_results where k='answer'),1,'answer marks chest shard round');
insert into reward_results values ('first',public.quiz_claim_chest_shards('dddddddd-dddd-4ddd-8ddd-dddddddddddd','combo'));
insert into reward_results values ('again',public.quiz_claim_chest_shards('dddddddd-dddd-4ddd-8ddd-dddddddddddd','combo'));
select is((select v from reward_results where k='first'),(select v from reward_results where k='again'),'claim repeats same receipt');
select throws_ok($$select public.quiz_answer('dddddddd-dddd-4ddd-8ddd-dddddddddddd',25::smallint)$$,'P0001','answered','answer cannot award items again');
select throws_ok($$delete from public.quiz_chest_shard_events$$,'42501',null,'receipt direct writes denied');
select lives_ok($$select public.quiz_reconcile_chest_shards()$$,'reconcile own receipts');
select set_config('request.jwt.claims','{"sub":"ffffffff-ffff-4fff-8fff-ffffffffffff","role":"authenticated"}',true);
select is((select count(*)::int from public.quiz_chest_shard_events),0,'another user sees no receipt');
select throws_ok($$select public.quiz_claim_chest_shards('dddddddd-dddd-4ddd-8ddd-dddddddddddd','combo')$$,'P0001','no_chest','another user cannot claim');
reset role;
set local role anon;
select throws_ok($$select public.quiz_claim_chest_shards('dddddddd-dddd-4ddd-8ddd-dddddddddddd','combo')$$,'42501',null,'anon denied');
reset role;
-- Deterministic sampler boundaries and aggregation, independent of live RNG.
create function pg_temp.entropy(n float8,g float8) returns jsonb language sql as $$
select jsonb_build_object('countRoll',n,'pieces',jsonb_build_array(
jsonb_build_object('groupRoll',g,'speciesRoll',0),jsonb_build_object('groupRoll',g,'speciesRoll',0),jsonb_build_object('groupRoll',g,'speciesRoll',0))) $$;
select is(public.quiz_draw_chest_shards('combo',pg_temp.entropy(0,0),1),'[]'::jsonb,'zero shards is a real draw');
select is(public.quiz_draw_chest_shards('combo',pg_temp.entropy(.75,0),1),'[{"speciesId":1,"count":3}]'::jsonb,'three repeated picks aggregate');
select is((public.quiz_draw_chest_shards('combo',pg_temp.entropy(.25,0),1)->0->>'count')::int,1,'quarter starts one');
select is((public.quiz_draw_chest_shards('combo',pg_temp.entropy(.5,0),1)->0->>'count')::int,2,'half starts two');
select ok((select (metadata->>'legendary')::boolean or (metadata->>'mythical')::boolean or (metadata->>'captureRate')::int<=45 from public.pokemon_shard_catalog where version=1 and pokemon_id=(public.quiz_draw_chest_shards('special',pg_temp.entropy(.25,.699999),1)->0->>'speciesId')::int),'below .70 picks rare');
select ok((select not ((metadata->>'legendary')::boolean or (metadata->>'mythical')::boolean or (metadata->>'captureRate')::int<=45) from public.pokemon_shard_catalog where version=1 and pokemon_id=(public.quiz_draw_chest_shards('special',pg_temp.entropy(.25,.7),1)->0->>'speciesId')::int),'.70 picks common');
select is((select count(*)::int from pg_proc where proname in ('quiz_draw_chest_shards','quiz_chest_entropy','quiz_chest_shard_settle') and has_function_privilege('authenticated',oid,'execute')),0,'sampler helpers private');
-- Missing catalog does not settle or redraw. Temporarily hide a row, rolled back.
alter table public.pokemon_shard_catalog disable trigger pokemon_shard_catalog_frozen;
create temp table hidden_catalog as select * from public.pokemon_shard_catalog where version=1 and pokemon_id=1;
delete from public.pokemon_shard_catalog where version=1 and pokemon_id=1;
update public.quiz_chest_shard_events set state='pending',entropy=pg_temp.entropy(.75,0),shards='[]' where kind='special';
select is(public.quiz_chest_shard_settle('dddddddd-dddd-4ddd-8ddd-dddddddddddd','special')->>'state','pending','partial catalog stays pending');
insert into public.pokemon_shard_catalog select * from hidden_catalog;
select is(public.quiz_chest_shard_settle('dddddddd-dddd-4ddd-8ddd-dddddddddddd','special')->>'state','awarded','catalog restored settles saved entropy');
reset role;
insert into public.quiz_rounds(id,user_id,answer_id,options,veil,hard,range_from,range_to,gifts,bonus_slot,duration_ms) values ('dddddddd-dddd-4ddd-8ddd-ddddddddddd2','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',25,array[25,1,2,3],'warp',false,1,151,array['oran-berry','oran-berry','oran-berry','oran-berry'],0,14000);
update public.quiz_rounds set chest_reward_version=null where id='dddddddd-dddd-4ddd-8ddd-ddddddddddd2';
update public.quiz_players set used=0,bonus=0,streak=4,records=0 where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","role":"authenticated"}',true);
insert into reward_results values ('legacy',public.quiz_answer('dddddddd-dddd-4ddd-8ddd-ddddddddddd2',25::smallint));
reset role;
select is((select jsonb_array_length(v->'chests') from reward_results where k='legacy'),1,'legacy round still pays its item chest');
select is((select v->'chest_reward_version' from reward_results where k='legacy'),'null'::jsonb,'legacy round is not a chest shard round');
select is((select count(*)::int from public.quiz_chest_shard_events where round_id='dddddddd-dddd-4ddd-8ddd-ddddddddddd2'),0,'legacy round gets no chest entitlement');
select is((select (v->>'lucky')::boolean from reward_results where k='legacy'),true,'bonus slot answered is lucky');
select is((select bonus::int from public.quiz_players where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'),0,'lucky at ten left adds no turn');
insert into public.quiz_rounds(id,user_id,answer_id,options,veil,hard,range_from,range_to,gifts,bonus_slot,duration_ms) values ('dddddddd-dddd-4ddd-8ddd-ddddddddddd3','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',25,array[25,1,2,3],'warp',false,1,151,array['oran-berry','oran-berry','oran-berry','oran-berry'],0,14000);
update public.quiz_players set used=1,bonus=0 where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';
set local role authenticated;
insert into reward_results values ('lucky9',public.quiz_answer('dddddddd-dddd-4ddd-8ddd-ddddddddddd3',25::smallint));
reset role;
select is((select (v->>'left')::int from reward_results where k='lucky9'),10,'lucky at nine left returns to ten');
select * from finish();
rollback;
